 "content": "def transform(grid):
    """Complete one-cell horizontal gaps and project each gap upward until blocked."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    sources = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                sources.append((r, c, color))
    for r, c, color in sorted(sources, reverse=True):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    return out
