 "content": "def transform(grid):
    """Fill single-cell horizontal gaps and project their colors upward, stopping at occupied cells."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    sources = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                sources.append((r, c, color))
    # Higher horizontal gaps establish their upward columns first; lower rays
    # stop when they reach an existing bar or a previously projected line.
    for r, c, color in sorted(sources):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    return out
