 "content": "def transform(grid):
    """Fill one-cell gaps in horizontal bars, then extend gap and marker columns upward."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    sources = []
    horizontal_rows = set()
    for r in range(h):
        # Horizontal bars are the multi-cell runs; their single-cell gaps are guide points.
        if any(grid[r][c] != 0 and grid[r][c + 1] == grid[r][c] for c in range(w - 1)):
            horizontal_rows.add(r)
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                sources.append((r, c, color))
    # Horizontal-bar gaps project upward, with higher bars taking precedence.
    for r, c, color in sorted(sources):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    # Separate vertical markers below the bars project upward until the first bar/ray.
    for r in range(h):
        if r in horizontal_rows:
            continue
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            for rr in range(r - 1, -1, -1):
                if out[rr][c] != 0:
                    break
                out[rr][c] = color
    return out
"
