 "content": "def transform(grid):
    """Fill one-cell horizontal gaps and extend vertical marker rays upward."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    bars = set()
    gaps = []
    for r in range(h):
        if any(grid[r][c] != 0 and grid[r][c] == grid[r][c + 1] for c in range(w - 1)):
            bars.add(r)
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))

    # Endpoint columns of repeated vertical marker segments extend upward.
    for c in range(w):
        r = 0
        while r < h:
            color = grid[r][c]
            if color == 0 or r in bars:
                r += 1
                continue
            end = r + 1
            while end < h and end not in bars and grid[end][c] == color:
                end += 1
            if end - r >= 2:
                for rr in range(r - 1, -1, -1):
                    if out[rr][c] != 0:
                        break
                    out[rr][c] = color
            r = end

    # A matching pair of isolated marks also defines parallel upward rays.
    for r in range(h):
        marks = [(c, color) for c, color in enumerate(grid[r]) if color and r not in bars]
