 "content": "def transform(grid):
    """Complete horizontal one-cell gaps; project only along bottom marker columns."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h:
        return out

    # Identify projection tracks from vertical rods reaching the bottom, or a
    # same-color pair of isolated bottom-edge markers.
    tracks = set()
    for c in range(w):
        color = grid[h - 1][c]
        if color == 0:
            continue
        length = 1
        r = h - 2
        while r >= 0 and grid[r][c] == color:
            length += 1
            r -= 1
        if length >= 2:
            tracks.add(c)
    bottom_counts = {}
    for color in grid[h - 1]:
        if color:
            bottom_counts[color] = bottom_counts.get(color, 0) + 1
    for c, color in enumerate(grid[h - 1]):
        if color and bottom_counts[color] >= 2:
            tracks.add(c)

    gaps = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                if c in tracks:
                    gaps.append((r, c, color))
    # Gaps on a marker track project upward, stopping at any existing object.
    for r, c, color in sorted(gaps):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    return out
