 "content": "def transform(grid):
    """Fill horizontal bar gaps and project the bottom markers upward."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h:
        return out

    # Mark rows containing a horizontal colored object, including a single-cell gap.
    bar_rows = set()
    for r in range(h):
        if any(grid[r][c] != 0 and grid[r][c] == grid[r][c + 1] for c in range(w - 1)):
            bar_rows.add(r)
        if any(grid[r][c] != 0 and grid[r][c] == grid[r][c + 2] and grid[r][c + 1] == 0 for c in range(w - 2)):
            bar_rows.add(r)

    # Close each single-cell gap within a horizontal row.
    for r in bar_rows:
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color

    # Bottom-edge marker columns extend upward, crossing bars and stopping at
    # any intervening non-bar object. Each bottom marker may have its own color.
    for c in range(w):
        color = grid[h - 1][c]
        if color == 0:
            continue
        r = h - 2
        while r >= 0 and grid[r][c] == color:
            r -= 1
        if h - 1 - r < 2:
            continue
        for rr in range(r, -1, -1):
            if rr not in bar_rows and grid[rr][c] != 0:
                break
            out[rr][c] = color
    return out
