            bar_rows.add(r)
        if any(grid[r][c] != 0 and grid[r][c] == grid[r][c + 2] and grid[r][c + 1] == 0 for c in range(w - 2)):
            bar_rows.add(r)

    gaps = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))

    # A filled horizontal gap extends upward until it hits another object.
    for r, c, color in sorted(gaps):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Vertical marker runs extend upward through empty cells, stopping at any bar/object.
    for c in range(w):
        r = 0
