            end = r + 1
            while end < h and end not in bar_rows and grid[end][c] == color:
                end += 1
            if end - r >= 2:
                for rr in range(r - 1, -1, -1):
                    if out[rr][c] != 0 or rr in bar_rows:
                        break
                    out[rr][c] = color
            r = end
    return out
