    w = len(grid[0]) if h else 0
    gaps = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))
    # Gap columns continue upward until the next occupied bar or marker.
    for r, c, color in sorted(gaps):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
