 "content": "def transform(grid):
    """Fill single-cell horizontal gaps and extend gaps/marker lines upward to blockers."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    gaps = []

    # Close every zero bracketed by the same nonzero color in a row.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gaps.append((r, c, color))

    # Each completed horizontal gap projects its color upward until blocked.
    for r, c, color in sorted(gaps):
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Repeated vertical marker segments project upward from their top endpoint.
    for c in range(w):
        r = 0
        while r < h:
            color = grid[r][c]
            if color == 0:
                r += 1
                continue
            end = r + 1
            while end < h and grid[end][c] == color:
                end += 1
            if end - r >= 2:
                for rr in range(r - 1, -1, -1):
                    if out[rr][c] != 0:
                        break
                    out[rr][c] = color
            r = end

    # A same-color pair of markers on one row also defines two vertical rays.
    for r in range(h):
        columns_by_color = {}
        for c, color in enumerate(grid[r]):
            if color != 0:
                columns_by_color.setdefault(color, []).append(c)
        for color, columns in columns_by_color.items():
            if len(columns) < 2:
                continue
            for c in columns:
                for rr in range(r - 1, -1, -1):
                    if out[rr][c] != 0:
                        break
                    out[rr][c] = color
    return out
