 "content": "def transform(grid):
    """For each marker, fill its aligned horizontal bar gaps and extend between them."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    # Identify bar-gap sites and complete them with their bar's color.
    gaps = {}
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                gaps.setdefault(c, []).append((r, color))
    for c, sites in gaps.items():
        # A vertical marker aligned with that column supplies the line color.
        markers = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0
                   and all(grid[r][c] != grid[r][cc] for cc in range(w) if cc != c)]
        if not markers:
            continue
        mr, mc = markers[-1]
        for r, bar_color in sites:
            out[r][c] = bar_color
        for r in range(mr - 1, -1, -1):
            if out[r][c] != 0:
                break
            out[r][c] = mc
    return out
